Configuration.parameter:
// Custom script connector that is more memory efficient 
// when we are talking about the search responses.

var socket = null;

// set to true if the server is accepting SSL connections
var useSSL = false;

// information for the TCP server we are connecting to
var host = "localhost";
var port = 100;

var parser = new com.ibm.di.parser.SPMLv2Parser();

function selectEntries()
{
	if (useSSL) 
		socket = java.net.ssl.SSLSocketFactory.getDefault().createSocket(host, port);
	else 
		socket = new java.net.Socket(host, port);

	os = socket.getOutputStream();

	//specify a source file, where the request is read from
	src = java.io.FileInputStream("examples/SPMLv2Parser/SearchRequest.xml");
	temp = java.io.ByteArrayOutputStream();

	var c = src.read();

	while (c != -1) {
		temp.write(c);
		c = src.read()
	}

	bytes = temp.toByteArray();
	temp = null;

	// use an HTTP-like headers to tell the TCP server what is comming.
	// the fist number that ends with '\n' is the length of the SPML request.
	head = java.lang.Integer.toString(bytes.length);
	os.write(head.getBytes("UTF-8"));
	os.write(10); 		// '\n'

	// write the SPML request.
	os.write(bytes);

	// make sure everithing is sent
	os.flush();

	// close the file since we do not need it any more...
	src.close();

	// This encoding is the encoding of the Response SPML that is comming back from the server.
	parser.setParam("characterSet","UTF-8");
	parser.setDebug(true);

	// in the Script Connector the "connector" variable is a reference to the Java Connector instance (i.e. this).
	connector.setParser(parser);
	connector.initParser(socket.getInputStream(), null);
}

// using this method the client will retrieve a single searchResponse, not all of the responses.
function getNextEntry ()
{
	readed = parser.readEntry(); 
	if (readed != null)
		entry.merge(readed);
	else
		result.setStatus(0);
}

function putEntry ()
{
}

function modEntry ()
{
}

function deleteEntry ()
{
}

function findEntry ()
{
}

function terminate(){
	socket.close();
	parser.closeParser();
}

Hook.Script:
var is = conn.getObject("tcp.inputstream");
var temp = new java.io.ByteArrayOutputStream();

// read the SPML request length
c = is.read();
while (c != 10) {
	temp.write(c);
	c = is.read();	
}

var lenStr = temp.toString("UTF-8");
var len = java.lang.Integer.parseInt(lenStr);

temp = new java.io.ByteArrayOutputStream();
for (i = 0; i < len; i++) {
	temp.write(is.read());
}

var input = new java.io.ByteArrayInputStream(temp.toByteArray());

var resEntry = system.newEntry();
var parser = new com.ibm.di.parser.SPMLv2Parser();

// this should be changed to the proper SPML request encoding.
parser.setParam("characterSet","UTF-8");
parser.setDebug(true);
parser.setInputStream(input);

parser.initParser();

resEntry = parser.readEntry();

// merge the retrieved Entry to the 'work' Entry, so that it can be processed further 
work.merge(resEntry);

var resEntry = system.newEntry();

// initialize an SPML parser, which transmits the responses through 
// the output stream of the TCP server
var parser = new com.ibm.di.parser.SPMLv2Parser();
parser.setOutputStream(work.getObject("tcp.outputstream"));
parser.setParam("characterSet", "UTF-8");
parser.initParser();

var send = system.newEntry();
send.setAttribute("spml.operation", "Search");
send.setAttribute("spml.operation.type", "Response");

// return the requested attributes in the response
var i=0;
while (i < work.getAttribute("spml.attributeDescription").size()) {
	var attName = work.getAttribute("spml.attributeDescription").getValue(i++);
	resEntry.addAttributeValue(attName, conn.getObject(attName));
}

// set the distinguishedName as an object id
resEntry.setAttribute("spml.psoID", conn.getAttribute("$dn"));
send.addAttributeValue("spml.resultEntries", resEntry);
parser.writeEntry(send);
parser.flush();

var name = work.getString("spml.filter.substrings.name");

var value = work.getString("spml.filter.substrings.final");

var search = system.newSearchCriteria();

search.addTemplate(name, com.ibm.di.server.SearchCriteria.SUBSTRING, value);

performSearch.setCriteria(search);

// set the base directory
performSearch.getConnector().setParam("ldapSearchBase", work.getString("spml.ContainerID"));

// set the search scope
performSearch.getConnector().setParam("ldapSearchScope", work.getString("spml.scope").toLowerCase());

var connector = performSearch.getConnector();

// initialize an SPML parser, which transmits the responses through 
// the output stream of the TCP server 
var parser = new com.ibm.di.parser.SPMLv2Parser();
parser.setOutputStream(work.getObject("tcp.outputstream"));
parser.setParam("characterSet", "UTF-8");
parser.initParser();

var send = system.newEntry();
send.setAttribute("spml.operation", "Search");
send.setAttribute("spml.operation.type", "Response");

// the first of all the entries.
var entry = connector.getFirstFindEntry();

// put all the found entries in the result
while (entry != null) {

	main.logmsg("========single entry========  " + entry);
	var resEntry = system.newEntry();

	// return the requested attributes in the response
	var i=0;
	while (i < work.getAttribute("spml.attributeDescription").size()) {
		var attName = work.getAttribute("spml.attributeDescription").getValue(i++);
		resEntry.addAttributeValue(attName, entry.getObject(attName));
	}

	// set the distinguishedName as an object id
	resEntry.setAttribute("spml.psoID", entry.getAttribute("$dn"));

	send.setAttribute("spml.resultEntries", resEntry);

	parser.writeEntry(send);

	// the next entry found
	entry = connector.getNextFindEntry();
}

parser.flush();

var resEntry = system.newEntry();

// initialize an SPML parser, which transmits the responses through 
// the output stream of the TCP server
var parser = new com.ibm.di.parser.SPMLv2Parser();
parser.setOutputStream(work.getObject("tcp.outputstream"));
parser.setParam("characterSet", "UTF-8");
parser.initParser();

var send = system.newEntry();
send.setAttribute("spml.operation", "Search");
send.setAttribute("spml.operation.type", "Response");

// set an empty entry for the blank result
send.addAttributeValue("spml.resultEntries", resEntry);

parser.writeEntry(send);
parser.flush();
